/**
 * Markdown rendering, for the copy and download actions.
 *
 * Markdown because it is what people paste into Discord, Reddit and notes apps,
 * which is where BG3 builds actually get shared.
 */

import { ABILITY_KEYS, ABILITY_LABELS, type Build, MAX_LEVEL } from './build';

const DISCLAIMER =
  'Generated by Classi, a fan-made tool with no affiliation to Baldur’s Gate 3, Larian Studios, or Wizards of the Coast.';

export function buildToMarkdown(build: Build, concept: string): string {
  const scores = ABILITY_KEYS.map(
    (key) => `${ABILITY_LABELS[key]} ${build.abilityScores[key]}`,
  ).join(' · ');

  const lines: string[] = [
    `# ${build.title}`,
    '',
    `> ${concept}`,
    '',
    `**Race:** ${build.race}`,
    `**Background:** ${build.background}`,
    `**Ability Scores:** ${scores}`,
    '',
  ];

  if (build.summary.trim().length > 0) {
    lines.push('## Summary', '', build.summary, '');
  }

  lines.push('## Progression', '');
  for (const level of build.levels) {
    lines.push(`### Level ${level.level} — ${level.progression}`, '');
    for (const entry of level.entries) {
      lines.push(`- **${entry.label}:** ${entry.detail}`);
    }
    lines.push('');
  }

  if (build.levels.length < MAX_LEVEL) {
    lines.push(
      `_This build stops at level ${build.levels.length} of ${MAX_LEVEL}; the response was cut short._`,
      '',
    );
  }

  if (build.roleplayNotes.trim().length > 0) {
    lines.push('## Roleplay', '', build.roleplayNotes, '');
  }

  lines.push('---', '', `_${DISCLAIMER}_`, '');

  return lines.join('\n');
}

/** A filesystem-safe filename for the download action. */
export function buildFilename(build: Build): string {
  const slug = build.title
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '')
    .slice(0, 60);
  return `${slug.length > 0 ? slug : 'classi-build'}.md`;
}
